"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {name: conversion_rate(groups[name]) if groups[name] else None
            for name in sorted(groups)}


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * max(0, end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"] - start_day] += 1
    return counts

"""Product analytics dashboard: conversion statistics over customer sessions."""
from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import pooled_conversion_rate, conversion_rate, conversions_in_window


def campaign_summary(groups, days):
    """Summary of groups of sessions. See SPEC.md section 7."""
    all_events = [e for evts in groups.values() for e in evts]
    if all_events:
        first = min(e["day"] for e in all_events)
        last = max(e["day"] for e in all_events)
        recent = conversions_in_window(daily_conversion_counts(all_events, first, last), days)
    else:
        recent = 0
    return {"rate": round(pooled_conversion_rate(groups), 3), "recent": recent,
            "groups": sum(1 for events in groups.values() if events)}


def top_converting_groups(groups, n):
    """The groups with the highest conversion rate. See SPEC.md section 8."""
    ranked = sorted((name for name, events in groups.items() if events),
                    key=lambda name: (-conversion_rate(groups[name]), name))
    return ranked[:max(0, n)]

import pytest

from sales_dashboard.loader import dedupe_sessions, daily_conversion_counts, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_and_handles_empty():
    groups = {"a": [session("a", 1, True)],
              "b": [session(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window_boundaries():
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 1) == 3
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 10) == 6
    assert conversions_in_window([], 1) == 0


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    assert parse_session_log(["\n", "  # ignored,not,a,session", "  a , 2 , 1 ",
                              " b, -1, 0 ", " c, 3,  "]) == [
        session("a", 2, True), session("b", -1, False), session("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_session_log_error_has_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", "ok,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts():
    early = session("x", 5, True)
    replacement = session("x", 1, False)
    a = session("a", 1, True)
    z = session("z", 2, None)
    assert dedupe_sessions([early, z, a, replacement]) == [a, replacement, z]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_pads_and_filters_range():
    events = [session("a", 1, True), session("b", 3, True),
              session("c", 3, True), session("d", 2, None),
              session("e", 4, True), session("f", 2, False)]
    assert daily_conversion_counts(events, 2, 3) == [0, 2]
    assert daily_conversion_counts(events, 0, 4) == [0, 1, 0, 2, 1]
    assert daily_conversion_counts([], 2, 4) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 2) == []


def test_campaign_summary_uses_calendar_days_and_pooled_rate():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, False), session("c", 4, False)], "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [session("b", 1, False)], "a": [session("a", 1, True)]}
    rates = conversion_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_conversion_streak_resets_on_nonpositive():
    assert longest_conversion_streak([1, 1, 0, 3, -1, 2, 3, 4]) == 3
    assert longest_conversion_streak([-1, 0]) == 0
    assert longest_conversion_streak([]) == 0
